function ReferralPromo({summary,onOpen,variant="home"}:{summary:ReferralSummary|null;onOpen:()=>void;variant?:"home"|"wallet"}){const total=summary?.total||0,qualified=summary?.qualified||0,target=summary?.target||3,reward=summary?.reward??500,remaining=Math.max(0,target-qualified),progress=Math.min(100,Math.round(qualified/target*100));return <button type="button" className={"referral-promo referral-promo-"+variant} onClick={onOpen}><span className="referral-promo-art"><span>↗</span><i/><b>SETHIS</b></span><span className="referral-promo-main"><span className="referral-promo-kicker">SETTLE THIS! · COMMUNITY REFERRALS</span><strong>Bring your football friends into SETHIS games.</strong><small>Invite real fans. Track every successful join. Earn milestone rewards.</small><span className="referral-promo-stats"><span><b>{total.toLocaleString()}</b><small>INVITED</small></span><span><b>{qualified.toLocaleString()}</b><small>QUALIFIED</small></span><span><b>{remaining.toLocaleString()}</b><small>TO MILESTONE</small></span></span><span className="referral-promo-progress"><i style={{width:progress+"%"}}/></span><span className="referral-promo-foot"><b>{qualified>=target?"MILESTONE COMPLETED":target+" QUALIFIED FRIENDS · "+reward.toLocaleString()+" SETHIS"}</b><strong>OPEN REFERRAL CENTRE ↗</strong></span></span></button>}
