  const loadProfile=async()=>{const initData=window.Telegram?.WebApp?.initData;if(!telegramUser||!initData){setProfileError("Open Settle This! inside Telegram to load your profile.");return;}setProfileLoading(true);setProfileError("");setProfileSaveError("");setProfileLoaded(false);try{const response=await fetch("/api/profile",{headers:{"x-telegram-init-data":initData}});const data=await response.json();if(!response.ok||!data.profile)throw new Error(data.error||"Your profile could not be loaded.");setProfileForm({club:data.profile.club||"",country:data.profile.country||"",bio:data.profile.bio||""});setProfileRank(Number.isFinite(data.rank)?Number(data.rank):null);setProfileAchievements(Array.isArray(data.achievements)?data.achievements:[]);setProfileHistory(data.history||{mystery_rounds:[],quizzes:[],transactions:[]});setProfileActivity(data.activity||{games_played:0,games_won:0,game_points:0,win_rate:0,quizzes_played:0,quizzes_passed:0,quiz_average:0,sethis_earned:0,ct_spent:0});setProfileLoaded(true);}catch(error){setProfileError(error instanceof Error?error.message:"Your profile could not be loaded. Please try again.");}finally{setProfileLoading(false);}};
  const saveProfile=async()=>{const initData=window.Telegram?.WebApp?.initData;if(!telegramUser||!initData||!profileLoaded||profileBusy)return;setProfileBusy(true);setProfileSaveError("");try{const response=await fetch("/api/profile",{method:"PUT",headers:{"content-type":"application/json","x-telegram-init-data":initData},body:JSON.stringify(profileForm)});const data=await response.json();if(!response.ok||!data.saved)throw new Error(data.error||"Profile could not be saved.");setProfileLoaded(true);showNotice("Your football profile has been updated.");setProfileOpen(false);}catch(error){setProfileSaveError(error instanceof Error?error.message:"Profile could not be saved. Please try again.");}finally{setProfileBusy(false);}};

