  const loadRankings=async()=>{setRankingLoading(true);setRankingError("");try{const initData=window.Telegram?.WebApp?.initData;const response=await fetch("/api/rankings",{headers:initData?{"x-telegram-init-data":initData}:{}});if(!response.ok)throw new Error("Rankings are temporarily unavailable.");const data=await response.json();setRankings(Array.isArray(data.rankings)?data.rankings:[]);setHomeStats({sethisEarned:Number(data.my_sethis_earned)||0,rank:data.my_rank===null||data.my_rank===undefined?null:Number(data.my_rank)});}catch(e){setRankingError(e instanceof Error?e.message:"Rankings are temporarily unavailable.");}finally{setRankingLoading(false);}};
  const loadNotifications=async()=>{const initData=window.Telegram?.WebApp?.initData;if(!telegramUser||!initData){setNotifications([]);setNotificationUnread(0);setNotificationError("");return;}setNotificationError("");try{const response=await fetch("/api/notifications",{headers:{"x-telegram-init-data":initData}});const data=await response.json();if(!response.ok)throw new Error(data.error||"Notifications could not be loaded.");setNotifications(Array.isArray(data.notifications)?data.notifications:[]);setNotificationUnread(Number(data.unread_count)||0);}catch(error){setNotificationError(error instanceof Error?error.message:"Notifications could not be loaded.");}};
  const markNotificationRead=async(notificationId:string):Promise<boolean>=>{const initData=window.Telegram?.WebApp?.initData;if(!initData)return false;try{const response=await fetch("/api/notifications/"+encodeURIComponent(notificationId)+"/read",{method:"POST",headers:{"x-telegram-init-data":initData}});if(!response.ok)throw new Error("Notification could not be marked as read.");const now=new Date().toISOString();let changed=false;setNotifications(rows=>rows.map(n=>{if(n.id!==notificationId||n.read_at)return n;changed=true;return {...n,read_at:now};}));if(changed)setNotificationUnread(n=>Math.max(0,n-1));return true;}catch(error){showNotice(error instanceof Error?error.message:"Notification could not be marked as read.");return false;}};
