  const joinSelectedCourt=async()=>{const initData=window.Telegram?.WebApp?.initData;if(!telegramUser||!initData||!selectedCourt||!courtSide){showNotice("Open SETHIS inside Telegram to access your games.");return;}try{const response=await fetch("/api/courts/"+encodeURIComponent(selectedCourt.id)+"/join",{method:"POST",headers:{"content-type":"application/json","x-telegram-init-data":initData},body:JSON.stringify({side:courtSide})});const data=await response.json();if(!response.ok){showNotice(data.error||"Court entry could not be completed.");return;}if(data.wallet)setWalletBalances({ct:Number(data.wallet.ct_balance)||0,sethis:Number(data.wallet.sethis_balance)||0});setCourtFeed(items=>items.map(item=>item.id===selectedCourt.id?{...item,side_a_count:Number(item.side_a_count)+(courtSide==="A"?1:0),side_b_count:Number(item.side_b_count)+(courtSide==="B"?1:0)}:item));if(courtArgument.trim())await fetch("/api/courts/"+encodeURIComponent(selectedCourt.id)+"/arguments",{method:"POST",headers:{"content-type":"application/json","x-telegram-init-data":initData},body:JSON.stringify({body:courtArgument.trim()})});setCourtOpen(false);setCourtArgument("");refreshMyCourts();showNotice("You're in. Your Court position has been recorded.");}catch{showNotice("Court entry could not be completed. Please try again.");}};
  const advanceOnboarding=async()=>{const initData=window.Telegram?.WebApp?.initData;if(!initData)return;const next=onboardingStep+1;setOnboardingError("");try{const response=await fetch("/api/onboarding/progress",{method:"POST",headers:{"content-type":"application/json","x-telegram-init-data":initData},body:JSON.stringify({step:next})});const data=await response.json();if(!response.ok||!data.saved)throw new Error(data.error||"Your progress could not be saved. Please try again.");setOnboardingStep(next);}catch(error){setOnboardingError(error instanceof Error?error.message:"Your progress could not be saved. Please try again.");}};
