        {taskItems.filter(task=>["telegram_channel","facebook_follow","whatsapp_community"].includes(task.task_key)).map(task=>{const fallbackLinks:Record<string,string>={telegram_channel:"https://t.me/",facebook_follow:"https://www.facebook.com/",whatsapp_community:"https://www.whatsapp.com/"};const destination=task.destination_url||fallbackLinks[task.task_key];const unavailable=task.claim_status==="pending"||task.claim_status==="approved";return <article className="task-row social-task-row" key={task.task_key}><span className="task-symbol brand-task-symbol">{task.task_key==="telegram_channel"?<img src="https://cdn.simpleicons.org/telegram/26A5E4" alt="Telegram"/>:task.task_key==="facebook_follow"?<img src="https://cdn.simpleicons.org/facebook/0866FF" alt="Facebook"/>:<img src="https://cdn.simpleicons.org/whatsapp/25D366" alt="WhatsApp"/>}</span><div><b>{task.title}</b><small>{task.claim_status==="pending"?"Awaiting verification":task.claim_status==="approved"?"Completed · reward credited":task.claim_status==="rejected"?"Not approved · you can try again":task.description}</small></div><div className="task-action-stack"><strong className="task-reward-amount">{task.reward_amount} SETHIS</strong><a className="task-action-button" href={unavailable?"#":destination} target="_blank" rel="noopener noreferrer" aria-disabled={unavailable} onClick={event=>{if(unavailable)event.preventDefault();}}>{task.claim_status==="approved"?"DONE":task.claim_status==="pending"?"PENDING":task.task_key==="facebook_follow"?"FOLLOW":"JOIN"}</a></div></article>;})}
